"""Offline protocol checks; formal data are never generated by these tests."""
import importlib.util
import hashlib
import json
import os
from pathlib import Path
import subprocess
import tempfile
import unittest
from unittest.mock import patch

BENCH = Path(__file__).resolve().parents[1]


def load_runner():
    spec = importlib.util.spec_from_file_location("biomedical_v04", BENCH / "v04.py")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


class RequestProtocolTest(unittest.TestCase):
    def test_c1_writes_io_inside_workspace_and_archives_after_exit(self):
        runner = load_runner()
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            prepared = root / "prepared"
            prepared.mkdir()
            (prepared / "input.rds").write_bytes(b"fixture-not-read-by-mocked-agent")
            (prepared / "dataset.sha256").write_text("fixture")
            (prepared / "task.json").write_text(json.dumps(dict(id="T02", instructions="test",
                prompts=["a", "b", "c"], steps=[])))
            def mocked_cli(config, directory, timeout):
                path = Path(config["child_env"]["GPTR_BENCH_IO_EVENTS"])
                self.assertTrue(path.is_relative_to(Path(config["workspace"])))
                path.write_text(json.dumps(dict(operation="rscript", file="<expression>",
                    request=1, started_unix=1, finished_unix=2, duration_ms=1000, bytes=None)) + "\n")
                return [dict(status="error", memory_scope="unavailable", exit_code=1)]
            with patch.object(runner.legacy, "codex_run", side_effect=mocked_cli):
                row = runner.run_arm("C1", 1, prepared, root, 30)
            self.assertEqual(row["status"], "error")
            self.assertTrue((root / "C1-1/io.jsonl").exists())


    def test_codex_cumulative_tokens_are_not_added_again_after_resume(self):
        runner = load_runner()
        with tempfile.TemporaryDirectory() as temporary:
            directory = Path(temporary)
            task = directory / "task.json"
            task.write_text(json.dumps(dict(id="T02", instructions="Analyze", prompts=["one", "two", "three"])))
            counter = []
            def measured(*args, **kwargs):
                counter.append(kwargs["prompt"])
                n = len(counter)
                for event in [dict(type="thread.started", thread_id="same-thread"),
                              dict(type="turn.completed", usage=dict(input_tokens=10*n, output_tokens=n))]:
                    kwargs["events"].append((1, json.dumps(event)+"\n"))
                return dict(status="ok", sampled_peak_rss_bytes=1, memory_scope="process_tree", exit_code=0)
            config = dict(task=str(task), codex_model="gpt-6.1-sol", workspace=temporary,
                          token_limit=1000, dataset_sha256="fixture")
            config["prompt_file"] = str(BENCH / "v0.5/aws/prompts.json")
            with patch.object(runner.legacy, "measure", side_effect=measured):
                result = runner.legacy.codex_run(config, directory, 30)[0]
            self.assertEqual(counter, json.loads((BENCH / "v0.5/aws/prompts.json").read_text())["T02"])
            self.assertEqual(result["input_tokens"], 30)
            self.assertEqual(result["output_tokens"], 3)

    def test_agent_definition_never_exposes_reference_steps(self):
        runner = load_runner()
        task = dict(id="T02", prompts=["one", "two", "three"], instructions="Analyze raw.",
                    steps=[dict(code="SECRET_CANONICAL_REFERENCE")], validation="PRIVATE_CHECKER")
        public = runner.agent_definition(task)
        self.assertEqual(set(public), {"id", "prompts", "instructions"})
        self.assertNotIn("SECRET_CANONICAL_REFERENCE", json.dumps(public))
        self.assertNotIn("PRIVATE_CHECKER", json.dumps(public))

    def test_c1_launcher_preserves_trailing_arguments_and_logs_rds(self):
        runner = load_runner()
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            env = {**os.environ, **runner.launchers(root / "private", root / "runtime"),
                   "GPTR_BENCH_IO_EVENTS": str(root / "io.jsonl"), "GPTR_BENCH_REQUEST": "2"}
            code = ("stopifnot(identical(commandArgs(TRUE), 'trailing')); "
                    "saveRDS(1:9,'input.rds'); stopifnot(length(base::readRDS('input.rds'))==9); "
                    "cat('stream\\n'); 2+3")
            result = subprocess.run([str(root / "runtime/bench-rscript"), "--vanilla", "-e",
                                     code, "trailing"], cwd=root, env=env,
                                    text=True, capture_output=True, timeout=30)
            self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
            self.assertEqual(result.stdout.strip(), "stream\n[1] 5")
            events = [json.loads(line) for line in (root / "io.jsonl").read_text().splitlines()]
            self.assertEqual([e["operation"] for e in events], ["saveRDS", "readRDS", "rscript"])
            self.assertTrue(all(e["request"] == 2 and e["success"] for e in events))

    def test_six_blocks_execute_in_three_requests_through_all_offline_arms(self):
        runner = load_runner()
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            prepared = root / "prepared"
            prepared.mkdir()
            made = runner.legacy.run_r("prepare", dict(input=str(prepared / "input.rds"),
                rows=None, task_id="clinical", task=str(prepared / "task.json"),
                environment=str(prepared / "environment.json"),
                session_info=str(prepared / "session-info.txt")), prepared, 30)
            self.assertEqual(made.returncode, 0, made.stdout + made.stderr)
            task = json.loads((prepared / "task.json").read_text())
            steps = []
            for request, step in enumerate(task["steps"], 1):
                steps.append({**step, "request": request})
                steps.append(dict(request=request, reads=["cohort"], writes=[],
                                  code="stopifnot(nrow(cohort) > 0)"))
            task["steps"] = steps
            runner.legacy.write_json(prepared / "task.json", task)
            (prepared / "dataset.sha256").write_text(hashlib.sha256(
                (prepared / "input.rds").read_bytes()).hexdigest())
            for arm, process_count, load_count in [("A2", 1, 1), ("C2", 3, 1), ("C3", 1, 1)]:
                row = runner.run_arm(arm, 1, prepared, root, 120)
                self.assertEqual(row["status"], "ok", row)
                self.assertEqual(row["r_processes"], process_count)
                self.assertEqual(row["tool_calls"], 6)
                self.assertEqual(row["input_loads"], load_count)
                check = json.loads((root / f"{arm}-1/evaluation.json").read_text())
                self.assertTrue(check["ok"])
                report_spec = importlib.util.spec_from_file_location("v04_test_timeline", BENCH / "v04_report.py")
                reporting = importlib.util.module_from_spec(report_spec)
                report_spec.loader.exec_module(reporting)
                reporting.timelines([row])
                self.assertTrue((root / f"{arm}-1/timeline.png").stat().st_size > 1000)

    def test_c2_loads_only_external_dependencies_once_per_request(self):
        runner = load_runner()
        steps = [
            dict(request=1, reads=["raw"], writes=["state"], code="state = raw"),
            dict(request=1, reads=["state"], writes=["derived"], code="derived = state"),
            dict(request=2, reads=["raw", "derived"], writes=["fit"], code="fit = derived"),
            dict(request=2, reads=["fit"], writes=["diagnostic"], code="diagnostic = fit"),
            dict(request=3, reads=["raw", "fit"], writes=[], code="print(fit)"),
        ]
        groups = runner.request_groups(steps)
        self.assertEqual(len(groups), 3)
        self.assertEqual(groups[0]["indices"], [1, 2])
        self.assertEqual(groups[0]["reads"], ["raw"])
        self.assertEqual(groups[0]["save"], ["derived"])
        self.assertEqual(groups[1]["reads"], ["raw", "derived"])
        self.assertEqual(groups[1]["save"], ["fit"])
        self.assertEqual(groups[2]["reads"], ["raw", "fit"])


    def test_io_events_include_readrds_and_saverds_in_isolated_child(self):
        with tempfile.TemporaryDirectory() as temporary:
            directory = Path(temporary)
            code = (
                "source(commandArgs(TRUE)[1]); "
                "bench_io_start(commandArgs(TRUE)[2], 'C1', 1); "
                "saveRDS(list(x=1:5000), 'input.rds', compress=FALSE); "
                "x=base::readRDS('input.rds'); stopifnot(length(x$x)==5000)"
            )
            result = subprocess.run(
                ["Rscript", "--vanilla", "-e", code, str(BENCH / "io.R"),
                 str(directory / "io.jsonl")], cwd=directory,
                text=True, capture_output=True, timeout=30,
            )
            self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
            events = [json.loads(line) for line in (directory / "io.jsonl").read_text().splitlines()]
            self.assertEqual([e["operation"] for e in events], ["saveRDS", "readRDS"])
            self.assertTrue(all(e["bytes"] > 0 and e["duration_ms"] >= 0 for e in events))
            self.assertTrue(all(e["pid"] > 0 and e["request"] == 1 for e in events))


if __name__ == "__main__":
    unittest.main()
